const Idol = (() => {
  const TURN = ['L', 'QL', 'F', 'QR', 'R'];
  const W = 80, H = 96, VX = 24, VY = 32;      // the assembly canvas, and the vessel's corner on it

  // The right-facing frames: mirror the left-facing ones, anchors and face too.
  const flip = ({ art, anchors }) => ({
    art: art.map((r) => [...r].reverse().join('')),
    anchors: Object.fromEntries(Object.entries(anchors).map(([k, v]) => {
      const box = (b) => [31 - b[2], b[1], 31 - b[0], b[3]];
      return [k, k === 'front' ? v.map(box) : v.length === 2 ? [31 - v[0], v[1]] : box(v)];
    })),
  });
  for (const set of Object.values(IDOL_PARTS)) {
    for (const piece of Object.values(set)) { piece.QR = flip(piece.QL); piece.R = flip(piece.L); }
  }

  /* One facing of an idol as rows of palette characters on the W x H canvas.
     `parts` names a creature for each piece: { mask, vessel, pedestal }. */
  function compose(parts, facing) {
    const m = IDOL_PARTS[parts.mask].mask[facing], v = IDOL_PARTS[parts.vessel].vessel[facing], p = IDOL_PARTS[parts.pedestal].pedestal[facing];
    const at = {
      vessel: [VX, VY],
      mask: [VX + v.anchors.neck[0] - m.anchors.neck[0], VY + v.anchors.neck[1] - m.anchors.neck[1]],
      pedestal: [VX + v.anchors.waist[0] - p.anchors.waist[0], VY + v.anchors.waist[1] - p.anchors.waist[1]],
    };
    const C = Array.from({ length: H }, () => Array(W).fill('.'));
    const draw = (piece, [ox, oy], keep = () => true) => piece.art.forEach((r, y) => [...r].forEach((c, x) => {
      if (c !== '.' && keep(x, y) && C[oy + y] && ox + x >= 0 && ox + x < W) C[oy + y][ox + x] = c;
    }));
    const front = v.anchors.front || [], [fx0, fy0, fx1, fy1] = m.anchors.face || [0, 0, -1, -1];
    const inFront = (x, y) => front.some(([x0, y0, x1, y1]) => x >= x0 && x <= x1 && y >= y0 && y <= y1);
    const onFace = (x, y) => {
      const mx = VX + x - at.mask[0], my = VY + y - at.mask[1];
      return mx >= fx0 && mx <= fx1 && my >= fy0 && my <= fy1 && m.art[my] && m.art[my][mx] !== '.';
    };
    draw(p, at.pedestal); draw(v, at.vessel); draw(m, at.mask);
    draw(v, at.vessel, (x, y) => inFront(x, y) && !onFace(x, y));
    return C;
  }

  /* Turn an idol on a canvas: left to right and back, a frame every FRAME_MS, at the largest whole
     scale that fits `box` (CSS px). The frame is the box around every facing of every combination,
     so the idol neither jumps as it turns nor changes size when a piece is swapped (set()).
     Stops on its own once the canvas leaves the page. */
  const FRAME_MS = 200;
  let bounds = null;
  function allBounds() {
    if (bounds) return bounds;
    const names = Object.keys(IDOL_PARTS);
    let x0 = W, x1 = 0, y0 = H, y1 = 0;
    for (const mask of names) for (const vessel of names) for (const pedestal of names) for (const f of TURN) {
      compose({ mask, vessel, pedestal }, f).forEach((r, y) => r.forEach((c, x) => {
        if (c !== '.') { x0 = Math.min(x0, x); x1 = Math.max(x1, x); y0 = Math.min(y0, y); y1 = Math.max(y1, y); }
      }));
    }
    return (bounds = { x0, x1, y0, y1 });
  }
  function play(canvas, parts, box) {
    const { x0, x1, y0, y1 } = allBounds();
    const w = x1 - x0 + 1, h = y1 - y0 + 1, s = Math.max(1, Math.floor(Math.min(box.w / w, box.h / h)));
    canvas.width = w * s; canvas.height = h * s;
    const g = canvas.getContext('2d'), seq = [...TURN.keys(), ...[3, 2, 1]];
    let frames = TURN.map((f) => compose(parts, f)), i = 0, cur = 0;
    const draw = () => {
      const C = frames[seq[cur]];
      g.clearRect(0, 0, canvas.width, canvas.height);
      for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) {
        const c = C[y][x];
        if (c === '.') continue;
        g.fillStyle = PAL[c];
        g.fillRect((x - x0) * s, (y - y0) * s, s, s);
      }
    };
    const step = () => {
      if (!canvas.isConnected) return;
      cur = i++ % seq.length;
      draw();
      setTimeout(step, FRAME_MS);
    };
    step();
    // Swap pieces mid-turn: the new idol shows at once, facing the same way.
    return { set(p) { frames = TURN.map((f) => compose(p, f)); draw(); } };
  }

  return { TURN, compose, play };
})();
